import type { ImageProps } from "./image.types";

import { useState, useEffect, useCallback, forwardRef, SyntheticEvent } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { ImageClasses, StyledImage } from "./image.styles";

const Image = forwardRef<HTMLImageElement, ImageProps>(
  ({ className, variant = "default", src, fallbackSrc, onSrcError, ...props }, ref) => {
    const theme = useTheme();
    const rootClasses = clsx(ImageClasses.root, className);
    const [imgSrc, setImgSrc] = useState<string | undefined>(fallbackSrc || src);
    const [attemptedSrc, setAttemptedSrc] = useState(false);

    useEffect(() => {
      setImgSrc(fallbackSrc || src);
      setAttemptedSrc(false);
    }, [src, fallbackSrc]);

    const handleLoad = useCallback(() => {
      if (!attemptedSrc) {
        setImgSrc(src);
        setAttemptedSrc(true);
      }
    }, [attemptedSrc, src]);

    const handleError = useCallback(
      (e: SyntheticEvent<HTMLImageElement, Event>) => {
        if (fallbackSrc) {
          setImgSrc(fallbackSrc);
        } else {
          setImgSrc(undefined);
        }
        if (imgSrc === fallbackSrc || !fallbackSrc) {
          onSrcError?.(e);
        }
      },
      [fallbackSrc, imgSrc, onSrcError],
    );

    return (
      <StyledImage
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        src={imgSrc}
        variant={variant}
        onError={handleError}
        onLoad={handleLoad}
        {...props}
      />
    );
  },
);

Image.displayName = "Image";

export default Image;
